map "https://fhir-sid.stage.opensrp.id/fhir/StructureMap/unicef-mexico-lactating-enrollment" = "Lactating"

uses "http://hl7.org/fhir/StructureDefinition/QuestionnaireReponse" as source
uses "http://hl7.org/fhir/StructureDefinition/Bundle" as target

group EnrollLactating(source src : QuestionnaireResponse, target bundle: Bundle) {
    src -> bundle.type = "collection" "r_bundle_type";
    src -> evaluate(src, $this.subject) as refPatient then
        ExtractEncounter(src, bundle, refPatient) "r_bundle_entries";
}

group ExtractEncounter(source src : QuestionnaireResponse, target bundle: Bundle, source refPatient: Patient,) {
    src -> bundle.entry as entry, entry.resource = create('Encounter') as encounter then {
        src -> encounter.id = uuid() "r_en_id";
        src -> encounter.status = 'finished' "r_en_st";
        src -> encounter.class = c("http://terminology.hl7.org/CodeSystem/v3-ActCode", "HH", "Home Health") "r_en_cls";
        src -> encounter.type = create('CodeableConcept') as concept then {
            src -> concept.coding = c("http://snomed.info/sct", "77386006") as coding then {
                src -> coding.display = 'Lactating Enrollment' "r_en_cod_disp";
            } "r_en_cc_cod";
            src -> concept.text = 'Lactating Enrollment' "r_en_typ_text";
        } "r_en_typ";
        src -> encounter.priority = create('CodeableConcept') as concept then {
            src -> concept.coding = c("http://snomed.info/sct", "17621005") as coding then {
                src -> coding.display = 'Normal' "r_en_cod_disp";
            } "r_en_cc_cod";
            src -> concept.text = 'Normal' "r_en_prio_text";
        } "r_en_prio";
    	src -> encounter.subject = evaluate(src, $this.subject) "r_en_sub";
        src -> encounter.period = create('Period') as enPeriod then {
            src -> enPeriod.start = evaluate(src, now()) "r_en_per_start";
            src -> enPeriod.end = evaluate(src, now()) "r_en_per_end";
        } "r_en_per";
        src -> encounter.reasonCode = create('CodeableConcept') as concept then {
            src -> concept.coding = c("http://smartregsiter.org/", "lactating") as coding then {
                src -> coding.display = 'Lactating Enrollment' "r_en_rc_cod_disp";
            } "r_en_rc_cod";
            src -> concept.text = 'Lactating Enrollment' "r_en_text";
        } "r_en_reason";

        src.item as item where(linkId = '834f9057-21b1-4ab6-c5d1-fbe97c488e96' and (answer.value.exists() and answer.value.code = '373066001')) then {
            src then ExtractRefs(src, bundle, encounter) "r_extract_obs";
          }"ruleReferralLinkIdExist";

    } "r_en";
}

group ExtractRefs(source src: QuestionnaireResponse, target bundle: Bundle, target encounter: Encounter) {
    src then
    extractLactatingCondition(src, bundle, encounter) "r_enc_refs";
}

group extractLactatingCondition(source src : QuestionnaireResponse, target bundle: Bundle, target encounter: Encounter){

        src -> bundle.entry as entry, entry.resource = create("Condition") as cnd then {
            src->cnd.id = uuid(),
                   cnd.encounter = reference(encounter),
                   cnd.subject  = evaluate(src, $this.subject)  "r_obs_data_date_of_lmp_gest_age_collection";
           src -> cnd.clinicalStatus = cc("http://terminology.hl7.org/CodeSystem/condition-clinical", "active") "r_cnd_clinical_st";
           src -> cnd.verificationStatus = cc("http://terminology.hl7.org/CodeSystem/condition-ver-status", "confirmed") "r_cnd_verif_st";
           src -> cnd.category = cc("http://terminology.hl7.org/CodeSystem/condition-category", "problem-list-item", "Problem List Item") "r_cnd_category";
           src -> cnd.recordedDate = evaluate(src, now()) "r_cnd_recorded";
           src -> encounter.reasonReference = create('Reference') as ref, ref.reference = evaluate(src,'Condition/' +cnd.id), ref.type = 'Condition' "r_obs_ref";
           src -> cnd.code = create("CodeableConcept") as ccPreg then {
                src -> ccPreg.coding = c("http://snomed.info/sct", "234234234", "Lactating") as coding, coding.display = 'Lactating' "r_cnd_code_coding";
                src -> ccPreg.text = "Lactating" "r_cnd_code_text";
           } "r_cnd_code";
       } "r_cnd";

}